package com.maintenance.maintenance_api.dto;

import lombok.*;

import java.time.Instant;

/**
 * PredictionDto is exclusively used for exposing ML predictions already stored in PostgreSQL.
 * Predictions are generated by the future Python ML / Airflow pipeline and are read-only via the REST API.
 */
@Getter
@Setter
@NoArgsConstructor
@AllArgsConstructor
@Builder
public class PredictionDto {
    private Long id;
    private Long machineId;
    private String machineIdentifier;
    private Instant timestamp;
    private String predictedComponent; // "none", "comp1", "comp2", "comp3", "comp4"
    private Double probability;
    private String modelVersion;
    private String status; // "NORMAL", "WARNING", "CRITICAL"
}
